// This file is generated by AI.

// 「内容变动后要不要补一次补全触发」的判据。
//
// 这条判据写错过一次, 症状是"确认补全后参数值列表不再自动弹出, 得手动删掉 `=` 再敲一次",
// 以及"删除字符时偶尔冒出 No suggestions"。两种写法只差一个字母, 因此在这里钉死:
//
// * 正确: 看**插入的文本**结尾是不是触发字符 (确认补全时语言服务补的 `-motion=` 正好命中);
// * 错误: 看**光标前那个字符** (删除之后光标前常常正好是 `=`, 于是删除也被当成一次触发)。

import { describe, expect, it } from 'vitest';

import { shouldRetriggerSuggest, isDeletionOnly, isSuggestableAfterDelete } from '../src/editor/suggest-retrigger';

const TRIGGERS = new Set([':', '-', '=', '{', '/', '\\', '"']);

describe('shouldRetriggerSuggest', () => {
  it('确认补全插入以触发字符结尾的片段 -> 要补一次', () => {
    expect(shouldRetriggerSuggest([{ text: 'motion=' }], TRIGGERS)).toBe(true);
    expect(shouldRetriggerSuggest([{ text: 'changeFigure:' }], TRIGGERS)).toBe(true);
    // 片段里的 `$0` 是占位符, Monaco 报的插入文本是它**展开后**的样子 (这里以 `-motion=` 为例)
    expect(shouldRetriggerSuggest([{ text: '-motion=' }], TRIGGERS)).toBe(true);
  });

  it('普通字符的插入 -> 不补 (交给 quickSuggestions 与原生触发)', () => {
    expect(shouldRetriggerSuggest([{ text: 's' }], TRIGGERS)).toBe(false);
    expect(shouldRetriggerSuggest([{ text: 'smile' }], TRIGGERS)).toBe(false);
  });

  it('**删除** -> 不补 (空文本), 否则会在无候选项处冒出 No suggestions', () => {
    expect(shouldRetriggerSuggest([{ text: '' }], TRIGGERS)).toBe(false);
    // 一次删除 + 一次普通插入也仍然是"不补"
    expect(shouldRetriggerSuggest([{ text: '' }, { text: 'a' }], TRIGGERS)).toBe(false);
  });

  it('多处改动里只要有一处命中就补', () => {
    expect(shouldRetriggerSuggest([{ text: 'a' }, { text: '-' }], TRIGGERS)).toBe(true);
  });

  it('空变动列表不补', () => {
    expect(shouldRetriggerSuggest([], TRIGGERS)).toBe(false);
  });
});

describe('isDeletionOnly', () => {
  it('纯删除 -> true (退格后要补一次列表)', () => {
    expect(isDeletionOnly([{ text: '' }])).toBe(true);
    // 多光标同时删除
    expect(isDeletionOnly([{ text: '' }, { text: '' }])).toBe(true);
  });

  it('有任何插入 -> false (插入走 `shouldRetriggerSuggest` 那条路)', () => {
    expect(isDeletionOnly([{ text: 'a' }])).toBe(false);
    expect(isDeletionOnly([{ text: '' }, { text: 'a' }])).toBe(false);
  });

  it('空变动列表 -> false', () => {
    expect(isDeletionOnly([])).toBe(false);
  });
});

describe('isSuggestableAfterDelete', () => {
  it('光标退到行首 -> 不补 (前面没有可补的上下文, 列表只会挡住上一行)', () => {
    expect(isSuggestableAfterDelete({ column: 1 })).toBe(false);
  });

  it('光标还在行内 -> 补 (删到 `-motion=smi` 时该看见 smile)', () => {
    expect(isSuggestableAfterDelete({ column: 2 })).toBe(true);
    expect(isSuggestableAfterDelete({ column: 12 })).toBe(true);
  });

  it('拿不到光标 (编辑器已销毁) -> 不补', () => {
    expect(isSuggestableAfterDelete(null)).toBe(false);
  });
});
